class Solution {
public:
    int sumOfUnique(vector<int>& nums) {
        int sum=0;
        sort(nums.begin(),nums.end());
        if(nums.size()==1)
            return nums[0];
        if(nums.size()==2)
            return nums[0]+nums[1];
        for(int i=1;i<nums.size()-1;i++){
           if(nums[i]!=nums[i+1]&&nums[i]!=nums[i-1])
               sum+=nums[i];
        }
        if(nums[0]!=nums[1])
            sum+=nums[0];
        if(nums[nums.size()-1]!=nums[nums.size()-2])
            sum+=nums[nums.size()-1];
        return sum;
    }
};

